// Characterization tests: pin current client-visible behavior, quirks included.
import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { apple: 10, pear: 10.5, gold: 60, free: 0 }
const pricing = { priceOf: async (sku) => prices[sku] }
let server, base

before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => new Promise((r) => server.close(r)))

const post = (body, raw) => fetch(`${base}/orders`, {
  method: 'POST',
  headers: { 'content-type': 'application/json' },
  body: raw ?? JSON.stringify(body),
})

async function create(items) {
  const res = await post({ items })
  return { res, body: await res.json() }
}

test('POST /orders creates an order: 201, json, id/items/total', async () => {
  const items = [{ sku: 'apple', qty: 2 }]
  const { res, body } = await create(items)
  assert.equal(res.status, 201)
  assert.equal(res.headers.get('content-type'), 'application/json')
  assert.deepEqual(Object.keys(body).sort(), ['id', 'items', 'total'])
  assert.equal(typeof body.id, 'string')
  assert.deepEqual(body.items, items)
  assert.equal(body.total, 20)
})

test('ids are distinct, numeric strings, increasing', async () => {
  const a = (await create([{ sku: 'apple', qty: 1 }])).body.id
  const b = (await create([{ sku: 'apple', qty: 1 }])).body.id
  assert.match(a, /^\d+$/)
  assert.equal(Number(b), Number(a) + 1)
})

test('total sums price * qty across items', async () => {
  const { body } = await create([{ sku: 'apple', qty: 2 }, { sku: 'gold', qty: 1 }])
  assert.equal(body.total, 80)
})

test('total is rounded down to whole euros', async () => {
  assert.equal((await create([{ sku: 'pear', qty: 1 }])).body.total, 10)
  assert.equal((await create([{ sku: 'pear', qty: 3 }])).body.total, 31)
})

test('10% discount only applies when total is strictly over 100', async () => {
  assert.equal((await create([{ sku: 'apple', qty: 10 }])).body.total, 100)
  assert.equal((await create([{ sku: 'apple', qty: 11 }])).body.total, 99) // 110 -> 99
  assert.equal((await create([{ sku: 'pear', qty: 10 }])).body.total, 100) // 105 -> 94.5 -> 94? see below
})

test('discount then floor: 101 -> 90', async () => {
  prices.odd = 101
  assert.equal((await create([{ sku: 'odd', qty: 1 }])).body.total, 90)
})

test('zero-priced items give total 0', async () => {
  assert.equal((await create([{ sku: 'free', qty: 5 }])).body.total, 0)
})

test('POST /orders rejects missing/empty/non-array items with 400', async () => {
  for (const body of [{}, { items: [] }, { items: 'x' }, { items: null }]) {
    const res = await post(body)
    assert.equal(res.status, 400)
    assert.deepEqual(await res.json(), { error: 'items required' })
  }
})

test('POST /orders rejects malformed JSON with 400', async () => {
  const res = await post(null, '{not json')
  assert.equal(res.status, 400)
  assert.deepEqual(await res.json(), { error: 'items required' })
})

test('POST /orders with empty body is 400', async () => {
  const res = await post(null, '')
  assert.equal(res.status, 400)
})

test('GET /orders/:id returns the stored order', async () => {
  const { body: created } = await create([{ sku: 'apple', qty: 3 }])
  const res = await fetch(`${base}/orders/${created.id}`)
  assert.equal(res.status, 200)
  assert.equal(res.headers.get('content-type'), 'application/json')
  assert.deepEqual(await res.json(), created)
})

test('GET unknown order returns 200 with {error: "not found"} (current quirk)', async () => {
  const res = await fetch(`${base}/orders/does-not-exist`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), { error: 'not found' })
})

test('unknown routes and methods return 404 {error: "no route"}', async () => {
  const cases = [
    ['GET', '/'], ['GET', '/orders'], ['GET', '/orders/1/extra'],
    ['PUT', '/orders'], ['DELETE', '/orders/1'], ['POST', '/orders/1'],
  ]
  for (const [method, path] of cases) {
    const res = await fetch(`${base}${path}`, { method })
    assert.equal(res.status, 404, `${method} ${path}`)
    assert.deepEqual(await res.json(), { error: 'no route' })
  }
})

test('query string is ignored when routing', async () => {
  const { body: created } = await create([{ sku: 'apple', qty: 1 }])
  const res = await fetch(`${base}/orders/${created.id}?x=1`)
  assert.deepEqual(await res.json(), created)
})
